const catalogue = [{id:"py",titre:"Python"},{id:"ja",titre:"Jardin"},{id:"we",titre:"Web"}];
function App() {
  const [recherche, setRecherche] = useState("");
  const critere = recherche.trim().toLowerCase();
  const visibles = catalogue.filter(a => a.titre.includes(recherche));
  return <main><button id="python" type="button" onClick={() => setRecherche("python")}>Chercher Python</button><button id="web" type="button" onClick={() => setRecherche("WEB")}>Chercher WEB</button><button id="sans-resultat" type="button" onClick={() => setRecherche("absent")}>Chercher absent</button><button id="tout" type="button" onClick={() => setRecherche("")}>Tout revoir</button><p id="critere">Critère : {recherche || "tous"}</p><ul id="liste">{visibles.map(a => <li key={a.id}>{a.titre}</li>)}</ul><p id="total">Résultats : {visibles.length}</p>{visibles.length === 0 ? <p id="vide">Aucun résultat.</p> : null}</main>;
}
root.render(<App />);

